; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcmin (Amstrad CPC - minimal firmware (own screen and keys, firmware for discs and ROMs)), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			; Option Class Interrupt: the classes' Tick subs, run at safe points (normal mode)
			ld hl, 300		; clock: every 300 interrupts
			ld (ntc_isl + 2), hl
			ld hl, 301			; the first after one period (+ the slot, so they take turns)
			ld (ntc_isl + 0), hl
			ld hl, p_clock_tick_c
			ld (ntc_isl + 6), hl
			ld hl, 0		; star: every frame
			ld (ntc_isl + 10), hl
			ld hl, 2			; the first after one period (+ the slot, so they take turns)
			ld (ntc_isl + 8), hl
			ld hl, p_star_tick_c
			ld (ntc_isl + 14), hl
			ld a, 2
			ld (ntc_isln), a
			ld hl, ntc_isl_tick
			ld (ntc_irqv), hl		; the interrupt handler counts for them
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen

			; Main.bas 8: Cls
			dw kw_cls

			; Main.bas 9: Locate 1, 3 : Print "Clock: a Tick once a second"
			dw kw_locatell, 1, 3
			dw kw_printzoscii
			dw glyph_43, glyph_6C, glyph_6F, glyph_63, glyph_6B, glyph_3A, glyph_20, glyph_61
			dw glyph_20, glyph_54, glyph_69, glyph_63, glyph_6B, glyph_20, glyph_6F, glyph_6E
			dw glyph_63, glyph_65, glyph_20, glyph_61, glyph_20, glyph_73, glyph_65, glyph_63
			dw glyph_6F, glyph_6E, glyph_64, 1, 0		; "Clock: a Tick once a second\n"

			; Main.bas 10: Locate 1, 4 : Print "Star: a Tick every frame (50 a second)"
			dw kw_locatell, 1, 4
			dw kw_printzoscii
			dw glyph_53, glyph_74, glyph_61, glyph_72, glyph_3A, glyph_20, glyph_61, glyph_20
			dw glyph_54, glyph_69, glyph_63, glyph_6B, glyph_20, glyph_65, glyph_76, glyph_65
			dw glyph_72, glyph_79, glyph_20, glyph_66, glyph_72, glyph_61, glyph_6D, glyph_65
			dw glyph_20, glyph_28, glyph_35, glyph_30, glyph_20, glyph_61, glyph_20, glyph_73
			dw glyph_65, glyph_63, glyph_6F, glyph_6E, glyph_64, glyph_29, 1, 0		; "Star: a Tick every frame (50 a second)\n"

			; Main.bas 11: Locate 1, 8 : Print "Press a key to stop"
			dw kw_locatell, 1, 8
			dw kw_printzoscii
			dw glyph_50, glyph_72, glyph_65, glyph_73, glyph_73, glyph_20, glyph_61, glyph_20
			dw glyph_6B, glyph_65, glyph_79, glyph_20, glyph_74, glyph_6F, glyph_20, glyph_73
			dw glyph_74, glyph_6F, glyph_70, 1, 0		; "Press a key to stop\n"

			; Main.bas 12: Do While Inkey <> 0 : Loop
do1_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do1_e
			dw do1_t_go
do1_e:

			; Main.bas 13: Do
do2_t:

			; Main.bas 14: loops = loops + 1
			dw kw_l_add, var_loops, llit_1, var_loops

			; Main.bas 15: Locate 1, 6 : Print "Main loop: "; loops;
			dw kw_locatell, 1, 6
			dw kw_printzoscii
			dw glyph_4D, glyph_61, glyph_69, glyph_6E, glyph_20, glyph_6C, glyph_6F, glyph_6F
			dw glyph_70, glyph_3A, glyph_20, 0		; "Main loop: "
			dw kw_l_print, var_loops

			; Main.bas 16: Loop Until Inkey <> 0
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_t
do2_e:

			; Main.bas 17: Locate 1, 10
			dw kw_locatell, 1, 10

			; Main.bas 18: Print "Clock ticked "; Clock.Seconds; " times, the star "; Star.Moves
			dw kw_printzoscii
			dw glyph_43, glyph_6C, glyph_6F, glyph_63, glyph_6B, glyph_20, glyph_74, glyph_69
			dw glyph_63, glyph_6B, glyph_65, glyph_64, glyph_20, 0		; "Clock ticked "
			dw kw_printint, var_clock_seconds
			dw kw_printzoscii
			dw glyph_20, glyph_74, glyph_69, glyph_6D, glyph_65, glyph_73, glyph_2C, glyph_20
			dw glyph_74, glyph_68, glyph_65, glyph_20, glyph_73, glyph_74, glyph_61, glyph_72
			dw glyph_20, 0		; " times, the star "
			dw kw_printint, var_star_moves
			dw kw_printnl

			; Main.bas 19: End
			dw kw_printnl0
			dw kw_printzoscii
			dw glyph_50, glyph_72, glyph_65, glyph_73, glyph_73, glyph_20, glyph_61, glyph_20
			dw glyph_6B, glyph_65, glyph_79, 0		; "Press a key"
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub tick (normal mode)
; ============================================================

p_clock_tick:

			; Clock.cls 5: Seconds = Seconds + 1
			dw kw_inc, var_clock_seconds

			; Clock.cls 6: Locate 30, 3 : Print Seconds; "s ";
			dw kw_locatell, 30, 3
			dw kw_printint, var_clock_seconds
			dw kw_printzoscii
			dw glyph_73, glyph_20, 0		; "s "
			dw p_clock_tick_r

; ============================================================
; sub tick (normal mode)
; ============================================================

p_star_tick:

			; Star.cls 6: Locate x + 1, 1 : Print " ";
			dw kw_addl, var_star_x, 1, tmp2
			dw kw_ltov, 1, tmp3
			dw kw_locatevv, tmp2, tmp3
			dw kw_printzoscii
			dw glyph_20, 0		; " "

			; Star.cls 7: x = (x + 1) Mod 39
			dw kw_addl, var_star_x, 1, tmp2
			dw kw_modvl, tmp2, 39, var_star_x

			; Star.cls 8: Locate x + 1, 1 : Print "*";
			dw kw_addl, var_star_x, 1, tmp2
			dw kw_ltov, 1, tmp3
			dw kw_locatevv, tmp2, tmp3
			dw kw_printzoscii
			dw glyph_2A, 0		; "*"

			; Star.cls 9: Moves = Moves + 1
			dw kw_inc, var_star_moves
			dw p_star_tick_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do1_t_go:			ld sp, do1_t
			jp ntc_xn

p_clock_tick_c:		; call tick (normal)
			ld (p_clock_tick_rs), sp
			ld sp, p_clock_tick
			jp ntc_xn
p_clock_tick_r:		; end of tick
			xor a			; Tick done: it may run again
			ld (ntc_isl + 4), a
			ld sp, (p_clock_tick_rs)
			jp ntc_xn
p_star_tick_c:		; call tick (normal)
			ld (p_star_tick_rs), sp
			ld sp, p_star_tick
			jp ntc_xn
p_star_tick_r:		; end of tick
			xor a			; Tick done: it may run again
			ld (ntc_isl + 12), a
			ld sp, (p_star_tick_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_loops:			dw 0, 0
var_clock_seconds:			dw 0
var_star_moves:			dw 0
p_clock_tick_rs:			dw 0
p_star_tick_rs:			dw 0
var_star_x:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0
tmp3:			dw 0

; numbers passed by address (read only)
llit_1:			dw 1, 0

; ============================================================
; ZOSCII glyphs - each points at its 8 byte bitmap in ntc_font
; ============================================================

glyph_20			equ ntc_font + 0		; " "
glyph_28			equ ntc_font + 64		; "("
glyph_29			equ ntc_font + 72		; ")"
glyph_2A			equ ntc_font + 80		; "*"
glyph_2C			equ ntc_font + 96		; ","
glyph_30			equ ntc_font + 128		; "0"
glyph_35			equ ntc_font + 168		; "5"
glyph_3A			equ ntc_font + 208		; ":"
glyph_43			equ ntc_font + 280		; "C"
glyph_4D			equ ntc_font + 360		; "M"
glyph_50			equ ntc_font + 384		; "P"
glyph_53			equ ntc_font + 408		; "S"
glyph_54			equ ntc_font + 416		; "T"
glyph_61			equ ntc_font + 520		; "a"
glyph_63			equ ntc_font + 536		; "c"
glyph_64			equ ntc_font + 544		; "d"
glyph_65			equ ntc_font + 552		; "e"
glyph_66			equ ntc_font + 560		; "f"
glyph_68			equ ntc_font + 576		; "h"
glyph_69			equ ntc_font + 584		; "i"
glyph_6B			equ ntc_font + 600		; "k"
glyph_6C			equ ntc_font + 608		; "l"
glyph_6D			equ ntc_font + 616		; "m"
glyph_6E			equ ntc_font + 624		; "n"
glyph_6F			equ ntc_font + 632		; "o"
glyph_70			equ ntc_font + 640		; "p"
glyph_72			equ ntc_font + 656		; "r"
glyph_73			equ ntc_font + 664		; "s"
glyph_74			equ ntc_font + 672		; "t"
glyph_76			equ ntc_font + 688		; "v"
glyph_79			equ ntc_font + 712		; "y"

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_ticks @data
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_div @data
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_ivar @data
ntc_ivar:		dw 0			; inputint / inkey: dest var

;## ntc_d_hook @data
ntc_hookon:		db 0			; 1 = the Interrupt hook may run (set, and not running now)
ntc_hookset:	db 0			; 1 = an Interrupt hook is set
ntc_hookpend:	db 0			; 1 = an interrupt came, the hook runs at the next safe point
ntc_hook:		dw 0			; the hook Sub's call stub

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xnh ntc_data ntc_islots @shared
; ntc_xn for a program with an Interrupt hook (Interrupt MySub) or interrupt
; classes (Option Class Interrupt): the same window, then a pending hook
; runs as a call of the hook Sub from this point (its return goes back into
; the thread), else a due class's Tick (not one still running). Flags are
; kept when nothing runs. Linked instead of ntc_xn.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			push af
			ld a, (ntc_hookpend)
			or a
			jr nz, ntc_xn_hookp
			ld a, (ntc_isldue)
			or a
			jr nz, ntc_xn_isl
ntc_xn_none:
			pop af
			ld sp, (ntc_ip)
			ret
ntc_xn_isl:
			ld hl, ntc_isl + 4		; the first slot due and not running
			ld a, (ntc_isln)
			ld b, a
			ld c, 0					; due but still running: stays due
ntc_xi_lp:
			ld a, (hl)
			or a
			jr nz, ntc_xi_skip
			inc hl
			ld a, (hl)
			dec hl
			or a
			jr nz, ntc_xi_run
ntc_xi_skip:
			inc hl
			ld a, (hl)
			dec hl
			or c
			ld c, a
			ld de, 8
			add hl, de
			djnz ntc_xi_lp
			ld a, c
			ld (ntc_isldue), a
			jr ntc_xn_none
ntc_xi_run:
			ld (hl), 1				; running (its return stub clears it)
			inc hl
			ld (hl), 0				; not due
			inc hl
			ld e, (hl)				; Tick's call stub
			inc hl
			ld d, (hl)
			pop af
			ld sp, (ntc_ip)
			ex de, hl
			jp (hl)
ntc_xn_hookp:
			pop af
ntc_xn_hook:
			xor a
			ld (ntc_hookpend), a
			ld (ntc_hookon), a	; not again until the hook returns
			ld sp, (ntc_ip)
			ld hl, (ntc_hook)
			jp (hl)

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_div ntc_data
; HL / DE signed, truncating. (ntc_mode) 0 = quotient, 1 = remainder.
; Remainder takes the dividend's sign. Divide by zero gives
; quotient 0, remainder = dividend. Pops destvar and stores.
ntc_div:
			ld a, d
			or e
			jr nz, ntc_div_nz
			ld a, (ntc_mode)
			or a
			jr nz, ntc_div_store
			ld hl, 0
			jr ntc_div_store
ntc_div_nz:
			ld a, h
			ld (ntc_sgnr), a
			xor d
			ld (ntc_sgnq), a
			bit 7, h
			jr z, ntc_div_hpos
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_hpos:
			bit 7, d
			jr z, ntc_div_dpos
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_div_dpos:
			ld a, h
			ld c, l
			ld hl, 0
			ld b, 16
ntc_div_loop:
			sla c
			rla
			adc hl, hl
			sbc hl, de
			jr nc, ntc_div_one
			add hl, de
			djnz ntc_div_loop
			jr ntc_div_done
ntc_div_one:
			inc c
			djnz ntc_div_loop
ntc_div_done:
			ld b, a
			ld a, (ntc_mode)
			or a
			jr z, ntc_div_q
			ld a, (ntc_sgnr)
			jr ntc_div_sign
ntc_div_q:
			ld h, b
			ld l, c
			ld a, (ntc_sgnq)
ntc_div_sign:
			rla
			jr nc, ntc_div_store
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_store:
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_divvl ntc_div
;kw_divvl, <var>, <literal>, <destvar>
kw_divvl:
			xor a
			ld (ntc_mode), a
ntc_divvl:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			pop de
			jp ntc_div

;## kw_modvl kw_divvl
;kw_modvl, <var>, <literal>, <destvar>
kw_modvl:
			ld a, 1
			ld (ntc_mode), a
			jp ntc_divvl

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_cpnevl ntc_cmp
kw_cpnevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_ne

; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE)
; ============================================================

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printzoscii ntc_data ntc_font ntc_plat_screen
;kw_printzoscii / dw glyph, glyph, ..., 0  - ZOSCII text inline in the thread
;  each word points at an 8 byte glyph bitmap. 1 = newline, 0 = end (only those two:
;  a program at #0040 can have glyphs below #0100)
kw_printzoscii:
			pop de
			ld a, d
			or a
			jr nz, ntc_pz_glyph
			ld a, e
			cp 2
			jr c, ntc_pz_ctl
ntc_pz_glyph:
			ld ix, kw_printzoscii
			jp ntc_plat_putglyph
ntc_pz_ctl:
			or a
			ret z
			ld ix, kw_printzoscii
			jp ntc_plat_newline

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inkey_got
			jp ntc_plat_scankey
ntc_inkey_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_scrinit ntc_data ntc_plat_screen
;kw_scrinit  - first word of any program that prints or reads keys:
;  mode 1, ROMs off, clear screen
kw_scrinit:
			ld a, 1
			ld ix, ntc_next
			jp ntc_plat_mode

;## kw_cls ntc_data ntc_plat_screen
;kw_cls
kw_cls:
			ld ix, ntc_next
			jp ntc_plat_cls

;## kw_locatell ntc_data ntc_plat_screen
;kw_locatell, <x>, <y>  - 1 based
kw_locatell:
			pop bc
			pop de
			ld h, c
			ld l, e
			ld ix, ntc_next
			jp ntc_plat_locate

;## kw_locatevv ntc_data ntc_plat_screen
;kw_locatevv, <xvar>, <yvar>
kw_locatevv:
			pop hl
			ld c, (hl)
			pop hl
			ld l, (hl)
			ld h, c
			ld ix, ntc_next
			jp ntc_plat_locate

;## ntc_ldata
ntc_la:			ds 4
ntc_lb:			ds 4
ntc_lr:			ds 4
ntc_lt:			ds 4
ntc_lsgn:		db 0
ntc_lcnt:		db 0
ntc_ldst:		dw 0
ntc_lix:		dw 0

;## kw_l_add
;kw_l_add, <a>, <b>, <dest>  - a + b
kw_l_add:
			pop hl
			pop de
			pop ix
			ld a, (de)
			add a, (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+3), a
			ret

;## ntc_ltoa ntc_ldata ntc_data
; Long at (HL) to text at DE, 0 at the end. jp (ix) back. Uses IY.
ntc_ltoa:
			ld (ntc_ldst), de
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			ld de, (ntc_ldst)
			ld a, (ntc_la+3)
			or a
			jp p, ntc_lta_pos
			ld a, '-'
			ld (de), a
			inc de
			ld hl, ntc_la
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
ntc_lta_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_lpow10
ntc_lta_pow:
			ld a, (iy+0)
			or (iy+1)
			or (iy+2)
			or (iy+3)
			jr z, ntc_lta_last
			ld c, '0'
ntc_lta_sub:
			ld hl, ntc_la
			ld a, (hl)
			sub (iy+0)
			ld (ntc_lt), a
			inc hl
			ld a, (hl)
			sbc a, (iy+1)
			ld (ntc_lt+1), a
			inc hl
			ld a, (hl)
			sbc a, (iy+2)
			ld (ntc_lt+2), a
			inc hl
			ld a, (hl)
			sbc a, (iy+3)
			ld (ntc_lt+3), a
			jr c, ntc_lta_dig
			ld hl, (ntc_lt)
			ld (ntc_la), hl
			ld hl, (ntc_lt+2)
			ld (ntc_la+2), hl
			inc c
			jr ntc_lta_sub
ntc_lta_dig:
			ld a, c
			cp '0'
			jr nz, ntc_lta_out
			ld a, (ntc_lead)
			or a
			jr z, ntc_lta_skip
			ld a, c
ntc_lta_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_lta_skip:
			ld bc, 4
			add iy, bc
			jr ntc_lta_pow
ntc_lta_last:
			ld a, (ntc_la)
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_lpow10:		dd 1000000000, 100000000, 10000000, 1000000, 100000, 10000, 1000, 100, 10, 0

;## kw_l_print ntc_ltoa ntc_printbuf
;kw_l_print, <long>  - print a Long
kw_l_print:
			pop hl
			ld de, ntc_numbuf
			ld ix, ntc_lpr_back
			jp ntc_ltoa
ntc_lpr_back:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_font
; 8x8 font buffer, chars 32-126, 8 bytes each, bit 7 = leftmost pixel.
; The platform fills it at start: the CPC copies its own font from the
; lower ROM (#3900), so text looks like the CPC's.
; glyph for char c = ntc_font + (c - 32) * 8
ntc_font:		ds 95 * 8

; ============================================================
; Platform class capabilities
; ============================================================

;## ntc_islots ntc_data @shared
; ------------------------------------------------------------
; ntc_islots - interrupt classes (Option Class Interrupt rate | Frame | Share n):
; up to 16 classes whose Tick Sub runs at the next safe point after it is due
; (normal mode). Slot n, 8 bytes at ntc_isl + n * 8:
;   +0 count (dw)  +2 reload (dw: interrupts between runs, 0 = every frame,
;   #8000 + weight = a shared class)  +4 running (db: Tick started, its return
;   stub clears it)  +5 due (db)  +6 Tick's call stub (dw)
; Fixed classes (a rate, Frame) are counted every interrupt. Shared classes take
; turns in the interrupts no fixed class fell due in: the current one is marked
; due on each such interrupt until it has had its weight of turns, then the
; next shared one. The start code fills the slots and puts ntc_isl_tick in
; ntc_irqv, which the platform's interrupt handler calls. The counts start a
; slot apart so classes of the same rate take turns.
; ------------------------------------------------------------
ntc_isln:		db 0			; slots in use
ntc_isldue:		db 0			; 1 = a slot may be due
ntc_islvs:		db 0			; vertical sync at the last interrupt
ntc_islfr:		db 0			; 1 = this interrupt is the frame's (sync just started)
ntc_islph:		db 0			; interrupts since the frame's (0-5)
ntc_islfx:		db 0			; 1 = a fixed class fell due in this interrupt
ntc_islsc:		db 0			; the shared class having its turns (slot number)
ntc_islsw:		db 0			; turns it has left
ntc_islshn:		db 0			; shared classes (0 = none)
ntc_isl:		ds 128			; 16 slots

; ntc_isl_tick - from the interrupt handler (call, real stack): count each
; slot, mark the ones due. Keeps BC, DE, IX, IY.
ntc_isl_tick:
			push bc
			push de
	IFDEF NTC_ZXN
			ld a, c					; zxn: the handler's frame flag in C (1: the line 0 interrupt)
	ELSE
			ld b, #F5				; PPI port B bit 0: vertical sync
			in a, (c)
	ENDIF
			and 1
			ld e, a
			ld a, (ntc_islvs)
			cpl
			and e
			ld d, a					; 1 = the sync started since the last interrupt
			ld a, e
			ld (ntc_islvs), a
			ld a, (ntc_islph)		; a frame is 6 interrupts: count them, so a frame is
			inc a					; still seen when this interrupt came in after the
			cp 6					; sync had ended (taken late: a long keyword); the
			jr c, ntc_it_ph			; sync puts the count back to 0
			xor a
ntc_it_ph:
			bit 0, d
			jr z, ntc_it_ph2
			xor a
ntc_it_ph2:
			ld (ntc_islph), a
			or a
			ld a, 0
			jr nz, ntc_it_fr
			inc a
ntc_it_fr:
			ld (ntc_islfr), a
			xor a
			ld (ntc_islfx), a
			ld a, (ntc_isln)
			or a
			jp z, ntc_it_end
			ld b, a
			ld hl, ntc_isl
ntc_it_lp:
			push hl
			inc hl
			inc hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			bit 7, d				; a shared class: the turns below mark it
			jr nz, ntc_it_nx
			ld a, d
			or e
			jr nz, ntc_it_rate
			ld a, (ntc_islfr)		; every frame: when the sync starts
			or a
			jr z, ntc_it_nx
			jr ntc_it_due
ntc_it_rate:
			ld e, (hl)
			inc hl
			ld d, (hl)
			dec de
			ld (hl), d
			dec hl
			ld (hl), e
			ld a, d
			or e
			jr nz, ntc_it_nx
			push hl					; due: count again from the reload
			inc hl
			inc hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			dec hl
ntc_it_due:
			push hl
			ld de, 5
			add hl, de
			ld (hl), 1
			pop hl
			ld a, 1
			ld (ntc_isldue), a
			ld (ntc_islfx), a
ntc_it_nx:
			ld de, 8
			add hl, de
			djnz ntc_it_lp
			; shared classes: an interrupt no fixed class used is a turn
			ld a, (ntc_islfx)
			or a
			jp nz, ntc_it_end
			ld a, (ntc_islshn)
			or a
			jp z, ntc_it_end
			ld a, (ntc_islsw)
			or a
			jr nz, ntc_it_take
			ld a, (ntc_islsc)		; its turns are used: the next shared class
ntc_it_find:
			inc a
			ld hl, ntc_isln
			cp (hl)
			jr c, ntc_it_fi2
			xor a
ntc_it_fi2:
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld de, ntc_isl + 2
			add hl, de
			ld e, (hl)				; E = the weight
			inc hl
			bit 7, (hl)
			jr z, ntc_it_find		; not shared (there is one: ntc_islshn)
			ld (ntc_islsc), a
			ld a, e
ntc_it_take:
			dec a
			ld (ntc_islsw), a
			ld a, (ntc_islsc)
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld de, ntc_isl + 5
			add hl, de
			ld (hl), 1				; due
			ld a, 1
			ld (ntc_isldue), a
ntc_it_end:
			pop de
			pop bc
			ret

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_smode:		db 1			; screen mode
ntc_sinit:		db 0			; 1 once the screen is set up
ntc_sbpc:		db 2			; bytes per char  \
ntc_scols:		db 40			; columns          | from ntc_modetab
ntc_smask:		db #F0			; pen 1 pixel mask |
ntc_sshift:		db 4			; glyph bits/byte /
ntc_pgstk:		ds 32			; putglyph: the stack an interrupt uses between characters
ntc_pgstk_top:
ntc_noadv:		db 0			; 1 = draw without moving the cursor
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line
ntc_pgrow:		db 0			; draw / scroll counter
ntc_pgaddr:		dw 0			; draw / scroll address
ntc_klink:		dw 0			; return for ntc_plat_getkey
ntc_kidx:		db 0			; key index found by the scan
ntc_kcur:		ds 10			; matrix this scan (0 = pressed)
ntc_kprev:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF
ntc_irqset:		db 0			; 1 = our interrupt handler is at #38
ntc_irqold:		ds 3			; the 3 bytes it replaced
ntc_irqhl:		dw 0			; handler scratch
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
	IF NTC_ROMLIB
ntc_uroff:		db 0			; (ROM) 1 = the upper ROM is off while the screen is read
	ENDIF
ntc_modetab:	db 4, 20, #C0, 2		; mode 0
				db 2, 40, #F0, 4		; mode 1
				db 1, 80, #FF, 8		; mode 2

; (ntc_plat_scroll, ntc_plat_cls: their own section - the ROM runs them from RAM)

;## ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_putc - A = character 32-126 (others print as ?), draw it
; ------------------------------------------------------------
ntc_plat_putc:
			sub 32
			jr c, ntc_pc_bad
			cp 95
			jr c, ntc_pc_ok
ntc_pc_bad:
			ld a, '?' - 32
ntc_pc_ok:
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld de, ntc_font
			add hl, de
			ex de, hl
			; fall into ntc_plat_putglyph

; ------------------------------------------------------------
; ntc_plat_putglyph - DE = 8 byte glyph, draw at the cursor, move on
; ------------------------------------------------------------
ntc_plat_putglyph:
			ld a, (ntc_cury)
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			ld b, h
			ld c, l
			add hl, hl
			add hl, hl
			add hl, bc			; HL = row * 80
			ld a, (ntc_sbpc)
			ld b, a
			ld a, (ntc_curx)
			ld c, a
			xor a
ntc_pg_mul:
			add a, c
			djnz ntc_pg_mul		; A = column * bytes per char
			ld c, a
			ld b, #C0
			add hl, bc			; HL = #C000 + row*80 + col*bpc
			ld a, (ntc_sbpc)		; mode 1 (2 bytes a row) and 2 (1 byte): their own loops
			cp 2
			jr z, ntc_pg_m1
			dec a
			jr z, ntc_pg_m2
			ld b, 8					; mode 0: 4 bytes a row, 2 pixels each (pen 1: bits 7, 6)
ntc_pg_m0lp:
			ld a, (de)
			inc de
			ld c, a
			and #C0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			ld c, a
			and #C0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			ld c, a
			and #C0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			and #C0
			ld (hl), a
			dec hl
			dec hl
			dec hl
			ld a, h
			add a, 8
			ld h, a
			djnz ntc_pg_m0lp
			jr ntc_pg_drawn
ntc_pg_m1:
			ld b, 8
ntc_pg_m1lp:
			ld a, (de)				; pen 1: pixels 0-3 in the high nibble, 4-7 next
			inc de
			ld c, a
			and #F0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			rlca
			rlca
			and #F0
			ld (hl), a
			dec hl
			ld a, h
			add a, 8
			ld h, a
			djnz ntc_pg_m1lp
			jr ntc_pg_drawn
ntc_pg_m2:
			ld b, 8
ntc_pg_m2lp:
			ld a, (de)
			inc de
			ld (hl), a
			ld a, h
			add a, 8
			ld h, a
			djnz ntc_pg_m2lp
ntc_pg_drawn:
			ld a, (ntc_nmode)		; normal mode: a waiting interrupt gets in after each
			or a					; character (drawing text is long), on a stack of its own
			jr z, ntc_pg_adv		; (SP may be the thread or the real stack here)
			ld (ntc_pgaddr), sp
			ld sp, ntc_pgstk_top
			ei
			nop
			di
			ld sp, (ntc_pgaddr)
ntc_pg_adv:
			ld a, (ntc_noadv)
			or a
			jr nz, ntc_pg_noadv
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pg_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pg_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do
ntc_pg_noadv:
			xor a
			ld (ntc_noadv), a
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_newline - column 0, next row, scroll at the bottom. Straight
; after a wrap at the last column it does nothing (as the firmware does)
; ------------------------------------------------------------
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jp nc, ntc_plat_scroll
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_mode @unit ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_mode - A = mode (0-2, 3 = 2). Gate array mode with both
; ROMs off, set text layout, clear screen
; ------------------------------------------------------------
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			ld (ntc_smode), a
			ld a, (ntc_sinit)
			or a
			jr nz, ntc_md_set
			; the first time: copy the CPC's own font (lower ROM, chars 32-126 at
			; #3900) into ntc_font. The copy runs from #C000 (screen RAM, cleared
			; just after), because the program itself can sit under the lower ROM
		IF NTC_ROMLIB
			jp ntc_fontcopy		; (ROM: it runs here - the lower ROM goes on, this one stays on)
		ELSE
			ld hl, ntc_fontcopy
			ld de, #C000
			ld bc, ntc_fontcopy_end - ntc_fontcopy
			ldir
			jp #C000
		ENDIF
ntc_md_set:
			ld a, (ntc_smode)
			ld c, a
		IF NTC_ROMLIB
			or #84				; (ROM: the upper ROM on)
		ELSE
			or #8C
		ENDIF
			ld b, #7F
			out (c), a
			ld a, 1
			ld (ntc_sinit), a
			ld a, c
			add a, a
			add a, a
			ld c, a
			ld b, 0
			ld hl, ntc_modetab
			add hl, bc
			ld de, ntc_sbpc
			ld bc, 4
			ldir
			jp ntc_plat_cls

; copied to #C000 and run there (no jumps inside: it runs at any address)
ntc_fontcopy:
		IF NTC_ROMLIB
			ld bc, #7F80		; lower ROM on, upper ROM (this one) on
		ELSE
			ld bc, #7F88		; lower ROM on, upper ROM off
		ENDIF
			out (c), c
			ld hl, #3900		; the firmware's character matrices, from char 32
			ld de, ntc_font
			ld bc, 95 * 8
			ldir
		IF NTC_ROMLIB
			ld bc, #7F84		; lower ROM off again
		ELSE
			ld bc, #7F8C		; both ROMs off again
		ENDIF
			out (c), c
			jp ntc_md_set
ntc_fontcopy_end:

;## ntc_plat_locate @unit ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_locate - H = column, L = row, 1 based, kept on screen
; ------------------------------------------------------------
ntc_plat_locate:
			xor a
			ld (ntc_wrapped), a
			ld a, h
			or a
			jr z, ntc_lc_x0
			dec a
ntc_lc_x0:
			ld c, a
			ld a, (ntc_scols)
			dec a
			cp c
			jr c, ntc_lc_xmax
			ld a, c
ntc_lc_xmax:
			ld (ntc_curx), a
			ld a, l
			or a
			jr z, ntc_lc_y0
			dec a
ntc_lc_y0:
			cp 25
			jr c, ntc_lc_ymax
			ld a, 24
ntc_lc_ymax:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_scroll ntc_plat_data ntc_data @shared @romram
; ------------------------------------------------------------
; ntc_plat_scroll - move rows 1-24 up one, clear row 24
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, 24
			ld (ntc_cury), a
			ld a, (ntc_nmode)		; normal mode: interrupts in during the long copy
			or a
			jr z, ntc_sc_open
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_sc_open:
		IF NTC_ROMLIB
			ld a, 1				; (ROM: the upper ROM off while the screen is read;
			ld (ntc_uroff), a	; the interrupt handler turns it on for its calls)
			ld a, (ntc_smode)
			or #8C
			ld b, #7F
			out (c), a
		ENDIF
			ld hl, #C000
			ld a, 8
ntc_sc_line:
			ld (ntc_pgrow), a
			ld (ntc_pgaddr), hl
			ld d, h
			ld e, l
			ld bc, 80
			add hl, bc
			ld bc, 24 * 80
			ldir
			ld h, d
			ld l, e
			ld (hl), 0
			inc de
			ld bc, 79
			ldir
			ld hl, (ntc_pgaddr)
			ld bc, #800
			add hl, bc
			ld a, (ntc_pgrow)
			dec a
			jr nz, ntc_sc_line
			di
		IF NTC_ROMLIB
			ld a, (ntc_smode)	; (ROM: the upper ROM on again)
			or #84
			ld b, #7F
			out (c), a
			xor a
			ld (ntc_uroff), a
		ENDIF
			ld a, (ntc_nmode)
			or a
			jr z, ntc_sc_close
			ld sp, (ntc_ip)
ntc_sc_close:
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_cls - clear screen memory, cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld a, (ntc_nmode)		; normal mode: interrupts in during the long copy
			or a
			jr z, ntc_cl_open
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_cl_open:
		IF NTC_ROMLIB
			ld a, 1				; (ROM: the upper ROM off - the fill reads the screen back)
			ld (ntc_uroff), a
			ld a, (ntc_smode)
			or #8C
			ld b, #7F
			out (c), a
		ENDIF
			ld hl, #C000
			ld de, #C001
			ld bc, #3FFF
			ld (hl), 0
			ldir
			di
		IF NTC_ROMLIB
			ld a, (ntc_smode)	; (ROM: the upper ROM on again)
			or #84
			ld b, #7F
			out (c), a
			xor a
			ld (ntc_uroff), a
		ENDIF
			ld a, (ntc_nmode)
			or a
			jr z, ntc_cl_close
			ld sp, (ntc_ip)
ntc_cl_close:
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_key ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_scankey - A = ASCII of a key pressed since the last scan,
; 0 if none
; ------------------------------------------------------------
ntc_plat_scankey:
			ld bc, #F40E		; PSG register 14
			out (c), c
			ld bc, #F6C0		; PSG: select register
			out (c), c
			ld bc, #F600		; PSG: inactive
			out (c), c
			ld bc, #F792		; PPI port A input
			out (c), c
			ld hl, ntc_kcur
			ld a, #40			; PSG read + line 0
ntc_ks_line:
			ld b, #F6
			out (c), a
			ld b, #F4
			in d, (c)
			ld (hl), d
			inc hl
			inc a
			cp #4A
			jr nz, ntc_ks_line
			ld bc, #F782		; PPI port A output
			out (c), c
			ld bc, #F600
			out (c), c
			ld a, #FF
			ld (ntc_kidx), a
			ld hl, ntc_kcur
			ld de, ntc_kprev
			ld iy, ntc_kign
			ld bc, #0A00		; B = 10 lines, C = key index
ntc_ks_find:
			ld a, (ntc_kidx)
			inc a
			jr nz, ntc_ks_next
			ld a, (hl)
			cpl
			ex de, hl
			and (hl)			; pressed now, released last scan
			ex de, hl
			and (iy+0)			; not shift / control / caps
			jr z, ntc_ks_next
ntc_ks_bit:
			rrca
			jr c, ntc_ks_got
			inc c
			jr ntc_ks_bit
ntc_ks_got:
			ld a, c
			ld (ntc_kidx), a
ntc_ks_next:
			ld a, c
			and #F8
			add a, 8
			ld c, a
			inc hl
			inc de
			inc iy
			djnz ntc_ks_find
			ld hl, ntc_kcur
			ld de, ntc_kprev
			ld bc, 10
			ldir
			ld a, (ntc_kidx)
			cp #FF
			jr z, ntc_ks_none
			ld e, a
			ld d, 0
			ld hl, ntc_keymap
			ld a, (ntc_kcur + 2)
			bit 5, a			; shift
			jr nz, ntc_ks_map
			ld hl, ntc_keymaps
ntc_ks_map:
			add hl, de
			ld a, (hl)
			jp (ix)
ntc_ks_none:
			xor a
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_getkey - wait for a key press, A = ASCII
; ------------------------------------------------------------
ntc_plat_getkey:
			ld (ntc_klink), ix
ntc_gk_scan:
			ld ix, ntc_gk_back
			jp ntc_plat_scankey
ntc_gk_back:
			or a
			jr nz, ntc_gk_done
			ld a, (ntc_nmode)		; normal mode: interrupts in while waiting
			or a
			jr z, ntc_gk_wait
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_gk_wait:
			ld bc, 1000			; about 6ms between scans (debounce)
ntc_gk_delay:
			dec bc
			ld a, b
			or c
			jr nz, ntc_gk_delay
			di
			ld a, (ntc_nmode)
			or a
			jr z, ntc_gk_scan
			ld sp, (ntc_ip)
			jr ntc_gk_scan
ntc_gk_done:
			ld ix, (ntc_klink)
			jp (ix)

; keys that never count as a press on their own (shift, control, caps)
ntc_kign:		db #FF, #FF, #5F, #FF, #FF, #FF, #FF, #FF, #BF, #FF

; matrix line 0-9, bit 0-7 -> ASCII (0 = ignored)
ntc_keymap:
			db 0, 0, 0, "9", "6", "3", 13, "."			; up right down f9 f6 f3 enter f.
			db 0, 0, "7", "8", "5", "1", "2", "0"		; left copy f7 f8 f5 f1 f2 f0
			db 0, "[", 13, "]", "4", 0, 92, 0			; clr [ return ] f4 shift \ control
			db "^", "-", "@", "p", ";", ":", "/", "."
			db "0", "9", "o", "i", "l", "k", "m", ","
			db "8", "7", "u", "y", "h", "j", "n", " "
			db "6", "5", "r", "t", "g", "f", "b", "v"
			db "4", "3", "e", "w", "s", "d", "c", "x"
			db "1", "2", 27, "q", 9, "a", 0, "z"		; 1 2 esc q tab a caps z
			db 0, 0, 0, 0, 0, 0, 0, 127				; joystick, del
ntc_keymaps:
			db 0, 0, 0, "9", "6", "3", 13, "."
			db 0, 0, "7", "8", "5", "1", "2", "0"
			db 0, "{", 13, "}", "4", 0, "`", 0
			db "^", "=", "|", "P", "+", "*", "?", ">"
			db "_", ")", "O", "I", "L", "K", "M", "<"
			db "(", 39, "U", "Y", "H", "J", "N", " "
			db "&", "%", "R", "T", "G", "F", "B", "V"
			db "$", "#", "E", "W", "S", "D", "C", "X"
			db "!", 34, 27, "Q", 9, "A", 0, "Z"
			db 0, 0, 0, 0, 0, 0, 0, 127

;## ntc_plat_irq ntc_plat_data ntc_data ntc_plat_irqh @shared
; ------------------------------------------------------------
; ntc_plat_irqon - put the interrupt handler at #38 (IM 1)
; ------------------------------------------------------------
ntc_plat_irqon:
			ld hl, (#0038)
			ld (ntc_irqold), hl
			ld a, (#003A)
			ld (ntc_irqold + 2), a
			ld a, #C3			; jp ntc_irq
			ld (#0038), a
			ld hl, ntc_irq
			ld (#0039), hl
			ld a, 1
			ld (ntc_irqset), a
			jp (ix)

;## ntc_plat_irqh ntc_plat_data ntc_data @shared @romram
; the handler: runs on the real stack, between keywords. Counts ticks
; (300 a second). AF goes to AF', HL to RAM; interrupt classes' counting
; (ntc_irqv) is a call, keeping the other registers.
ntc_irq:
			ex af, af'
			ld (ntc_irqhl), hl
			ld hl, (ntc_ticks)
			inc hl
			ld (ntc_ticks), hl
			ld a, (ntc_hookon)	; an Interrupt hook: run it at the next safe point
			or a
			jr z, ntc_irq_nohook
			ld (ntc_hookpend), a
ntc_irq_nohook:
			ld hl, (ntc_irqv)		; interrupt classes (Option Class Interrupt): count them
			ld a, h
			or l
		IF NTC_ROMLIB
			call nz, ntc_irq_rom	; (the handler runs on the real stack)
		ELSE
			call nz, ntc_irq_jp		; (the handler runs on the real stack)
		ENDIF
			ld hl, (ntc_irqhl)
			ex af, af'
			ei
			ret
ntc_irq_jp:
			jp (hl)
		IF NTC_ROMLIB
; (ROM) the counting is in the main ROM of the set: the upper ROM on and the
; main ROM selected for the call (the screen code may have the upper ROM off,
; a far routine may have another ROM of the set in), then both as they were
ntc_irq_rom:
			push bc
			ld a, (ntc_smode)
			or #84
			ld b, #7F
			out (c), a
			ld bc, (ntc_rx_s0)		; B = #DF, C = the main ROM's slot
			out (c), c
			call ntc_irq_jp
			ld bc, (ntc_rx_cur)		; the ROM that was in
			out (c), c
			ld a, (ntc_uroff)
			or a
			jr z, ntc_irq_ron
			ld a, (ntc_smode)
			or #8C
			ld b, #7F
			out (c), a
ntc_irq_ron:
			pop bc
			ret
		ENDIF

;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - before returning to the caller: interrupt handler
; out, upper ROM back on (lower off) if the screen was set up
; ------------------------------------------------------------
ntc_plat_exit:
			ld bc, #7FC0		; RAM setting back to plain (a Memory page may be in #4000)
			out (c), c
			ld a, (ntc_irqset)
			or a
			jr z, ntc_ex_rom
			ld hl, (ntc_irqold)
			ld (#0038), hl
			ld a, (ntc_irqold + 2)
			ld (#003A), a
			xor a
			ld (ntc_irqset), a
ntc_ex_rom:
			ld a, (ntc_sinit)
			or a
			jr z, ntc_ex_done
			ld a, (ntc_smode)
			or #84
			ld b, #7F
			out (c), a
ntc_ex_done:
			jp (ix)

; ============================================================
; Firmware calls (FileSystem, System.Command) - AMSDOS and other ROMs
; through the firmware, on a platform that otherwise doesn't use it. Each call hands
; the machine back for its length (fs_fwon / fs_fwoff): the firmware's
; interrupt entry at #38 and interrupts on (AMSDOS times the motor with
; firmware events), then NTC's handler, mode and ROM setting and the
; screen start again. Needs: the firmware's RAM intact (#A700-#BFFF:
; the program must end below #A600, checked when assembling), AMSDOS
; running (Option RomEnable 7 after RUN"). While a file call runs the
; screen may show the firmware's mode, and its messages (disc missing,
; Retry / Cancel) appear on NTC's screen.
; The rest is the cpcfw platform's file code (CAS IN / OUT DIRECT, |TAPE,
; |DISC, volumes as AMSDOS commands).
; ============================================================
FS_NOTFOUND	equ -2
FS_TOOBIG	equ -8
FS_FAILED	equ -9
FS_BADNAME	equ -4


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
			SAVEAMSDOS "INTERRUP.BIN", ntc_start, ntc_end - ntc_start, ntc_start
